        console.log('  Date:', date);
        console.log('    Status:', info.status);
        if (info.prices) console.log('    Prices:', JSON.stringify(info.prices));
        if (info.available_seats) console.log('    Seats:', JSON.stringify(info.available_seats));
    }
} else {
    console.log('Flight FLD3D594 NOT found.');
    console.log('\\nSearching LAX to SFO flights:');
    const laxSfo = db.prepare(\"SELECT * FROM flights WHERE origin = 'LAX' AND destination = 'SFO'\").all();
    laxSfo.forEach(f => {
        const dates = JSON.parse(f.dates_json || '{}');
        console.log('  ' + f.flight_id + ': ' + f.origin + '->' + f.destination + ' dep=' + f.departure_time + ' arr=' + f.arrival_time);
        for (const [date, info] of Object.entries(dates)) {
            console.log('    ' + date + ': ' + info.status + (info.prices ? ' prices=' + JSON.stringify(info.prices) : ''));
        }
    });
    console.log('\\nSearching for flights with FLD3D in ID:');
    const partial = db.prepare(\"SELECT flight_id, origin, destination FROM flights WHERE flight_id LIKE '%FLD3D%'\").all();
    partial.forEach(f => console.log('  ' + f.flight_id + ': ' + f.origin + '->' + f.destination));
}
"

