cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// === Parameters ===
const userId = 'user_fa209a3f';
const flightId = 'FLD3D594';
const flightDate = '2026-09-10';
const cabin = 'economy';
const flightType = 'one_way';
const origin = 'LAX';
const destination = 'SFO';
const passenger = { first_name: 'Maya', last_name: 'Chen', dob: '1987-04-16' };
const paymentId = 'cc_2402ef91';
const totalBaggages = 2;   // silver + economy = 2 free
const nonfreeBaggages = 0;
const insurance = 'no';

// === Load flight data ===
const flightRow = db.prepare('SELECT * FROM flights WHERE flight_id = ? AND source_skill = ?').get(flightId, 'tau2Airline');
const dates = JSON.parse(flightRow.dates_json);
const dateInfo = dates[flightDate];

if (dateInfo.status !== 'available') { console.log('ERROR: Flight not available'); process.exit(1); }
if (dateInfo.available_seats[cabin] < 1) { console.log('ERROR: No seats'); process.exit(1); }

const price = dateInfo.prices[cabin]; // 129
const totalPrice = price * 1 + 0 + 0; // 1 passenger, 0 extra bags, no insurance
console.log('Price per passenger:', price);
console.log('Total price:', totalPrice);

// === Generate reservation ID (mimicking tool logic) ===
const existingIds = db.prepare(\"SELECT booking_id FROM flight_bookings WHERE source_skill = 'tau2Airline'\").all().map(r => r.booking_id);
let reservationId = null;
for (const candidate of ['HATHAT', 'HATHAU', 'HATHAV']) {
    if (!existingIds.includes(candidate)) { reservationId = candidate; break; }
}
if (!reservationId) { console.log('ERROR: Too many reservations'); process.exit(1); }
console.log('Reservation ID:', reservationId);

// === Deduct seats ===
dateInfo.available_seats[cabin] -= 1;
const updatedDatesJson = JSON.stringify(dates);
db.prepare('UPDATE flights SET dates_json = ? WHERE flight_id = ? AND source_skill = ?')
  .run(updatedDatesJson, flightId, 'tau2Airline');

// === Insert reservation ===
const flightsJson = JSON.stringify([{
    flight_id: flightId,
    flight_number: flightId,
    origin: origin,
    destination: destination,
    date: flightDate,
    price: price
}]);
const passengersJson = JSON.stringify([passenger]);
const paymentHistoryJson = JSON.stringify([{ payment_id: paymentId, amount: totalPrice }]);
const bookedAt = '2024-05-15T15:00:00';

db.prepare(
    'INSERT INTO flight_bookings (booking_id, user_id, origin, destination, flight_type, cabin_class, flights_json, passengers_json, payment_history_json, booked_at, total_baggages, nonfree_baggages, add_insurance, status, source_skill) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)'
).run(
    reservationId, userId, origin, destination, flightType, cabin,
    flightsJson, passengersJson, paymentHistoryJson,
    bookedAt, totalBaggages, nonfreeBaggages, insurance, 'confirmed', 'tau2Airline'
);

console.log('Reservation inserted successfully.');

// === Verify ===
const res = db.prepare('SELECT * FROM flight_bookings WHERE booking_id = ?').get(reservationId);
console.log('\\n=== Booking Confirmation ===');
console.log('Reservation ID:', res.booking_id);
console.log('User:', res.user_id);
console.log('Route:', res.origin, '->', res.destination);
console.log('Flight Type:', res.flight_type);
console.log('Cabin:', res.cabin_class);
console.log('Flights:', res.flights_json);
console.log('Passengers:', res.passengers_json);
console.log('Payment:', res.payment_history_json);
console.log('Baggages:', res.total_baggages, '(free:', res.total_baggages - res.nonfree_baggages, ', paid:', res.nonfree_baggages, ')');
console.log('Insurance:', res.add_insurance);
console.log('Status:', res.status);

// Verify seat update
const updatedFlight = db.prepare('SELECT dates_json FROM flights WHERE flight_id = ?').get(flightId);
const updatedDates = JSON.parse(updatedFlight.dates_json);
console.log('\\nRemaining economy seats on', flightDate + ':', updatedDates[flightDate].available_seats[cabin]);
"
